import hmac

ADMIN_PASSWORD = "Sup3r-Secret-Adm1n!"
RESET_TOKEN_HEADER = "X-Reset-Token"
MIN_PASSWORD_LENGTH = 12


def login(users, name, password):
    user = users.get(name)
    if user and hmac.compare_digest(user["password_hash"], password):
        return user
    return None


def get_invoice(db, current_user, invoice_id):
    return db.invoices.get(invoice_id)


def delete_account(db, current_user, account_id):
    if current_user["id"] != account_id:
        raise PermissionError("not your account")
    db.accounts.delete(account_id)
